def get_pairs(word):
    return set(zip(word[:-1],word[1:]))
def bpe(token):
    word=tuple(token)
    pairs=get_pairs(word)
    if not pairs:return token
    while True:
        bigram=min(pairs,key=lambda p:bpe_ranks.get(p,1e18))
        if bigram not in bpe_ranks:break
        first,second=bigram
        new=[];i=0
        while i<len(word):
            try:
                j=word.index(first,i);new.extend(word[i:j]);i=j
            except:
                new.extend(word[i:]);break
            if word[i]==first and i<len(word)-1 and word[i+1]==second:
                new.append(first+second);i+=2
            else:
                new.append(word[i]);i+=1
        word=tuple(new)
        if len(word)==1:break
        pairs=get_pairs(word)
    return word
def encode(text):
